    case "MemoryItem":
      if #available(iOS 27.0, macOS 27.0, *) {
        try await Self.update(
          AssistantSnapshot.records("MemoryItem").map(MemoryItemEntity.init(record:)),
          removed: removedIDs, clearFirst: clearFirst)
